CREATE TABLE ezcontentobject (id INT AUTO_INCREMENT NOT NULL, contentclass_id INT DEFAULT 0 NOT NULL, current_version INT DEFAULT NULL, initial_language_id BIGINT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, modified INT DEFAULT 0 NOT NULL, name VARCHAR(255) DEFAULT NULL, owner_id INT DEFAULT 0 NOT NULL, published INT DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT NULL, section_id INT DEFAULT 0 NOT NULL, status INT DEFAULT 0, is_hidden TINYINT(1) DEFAULT '0' NOT NULL, INDEX ezcontentobject_classid (contentclass_id), INDEX ezcontentobject_lmask (language_mask), INDEX ezcontentobject_pub (published), INDEX ezcontentobject_section (section_id), INDEX ezcontentobject_currentversion (current_version), INDEX ezcontentobject_owner (owner_id), INDEX ezcontentobject_status (status), UNIQUE INDEX ezcontentobject_remote_id (remote_id), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
